-- part 1: Featherbone confirmed (90 proof, mash bill); Corsets, Whips & Whiskey re-typed wheat whiskey (page states no proof, stays seed); then 18 additions.
update cellar.products set mash_style = 'traditional', mash_bill = '70% corn, 25% wheat, 5% rye', producer = coalesce(producer, 'Journeyman'), producer_id = coalesce(producer_id, '735bb24a-1063-443b-8d85-68296e3afbb2'::uuid), source = 'maker', status = 'confirmed', source_url = 'https://www.journeyman.com/spirits/featherbone-bourbon/', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '105ec17c-e758-442c-b48c-59b31c000401' and facts_verified_at is null;
update cellar.products set spirit_type = 'wheat_whiskey', mash_style = 'wheated', producer = coalesce(producer, 'Journeyman'), producer_id = coalesce(producer_id, '735bb24a-1063-443b-8d85-68296e3afbb2'::uuid), source_url = 'https://www.journeyman.com/spirits/corsets-whips-whiskey/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'allocated'::cellar.rarity) where id = '093a34bf-0993-4df0-ab2e-31224b235c39' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('105ec17c-e758-442c-b48c-59b31c000401', '093a34bf-0993-4df0-ab2e-31224b235c39');
